    ("transferred", "restructuring"), ("transferred", "human"), ("transferred", "support"),
    ("no_promise", "refused"), ("no_promise", "hardship"), ("no_promise", "dispute"), ("no_promise", "service_error"),
    ("not_verified", "failed"), ("not_verified", "declined"),
